def problem_key(msg):
    """Message d'erreur brut (pyserial, socket, tinySA) -> clé de PROBLEM_CARDS."""
    low = str(msg or "").lower()
    return next((k for k, rx in _PROBLEM_KEYS if re.search(rx, low)), "other")


