        self.b_no = bb.addButton("▶ Démarrer sans enregistrer", QtWidgets.QDialogButtonBox.ButtonRole.ActionRole)
        self.b_rec.setToolTip("Démarre le scan et enregistre tout dans le dossier ci-dessus.")
