        self.site_bar = QtWidgets.QFrame()          # 📡 « aucun tinySA ne surveille cette scène » + boutons
        self.site_bar.setStyleSheet("QFrame { background:#3a2a00; border:1px solid #d29922; border-radius:4px; }")
